  import { PrismaClient } from '@prisma/client'
  const prisma = new PrismaClient()

// FIND
  const user = await prisma.user.findUnique({ where: { id: 1 } })
  const user = await prisma.user.findUniqueOrThrow({ where: { id: 1 } })
  const users = await prisma.user.findMany()
  const users = await prisma.user.findMany({
    where: {
      role: 'ADMIN',
      createdAt: { gte: new Date('2024-01-01') }
    },
    orderBy: { name: 'asc' },
    skip: 20,
    take: 10,                    // OFFSET 20 LIMIT 10
    select: {                    // only these fields (like .Select())
      id: true,
      name: true,
      email: true,
    }
  })

// RELATIONS — include (eager load, like .Include())
  const userWithPosts = await prisma.user.findUnique({
    where: { id: 1 },
    include: {
      posts: {
        where: { published: true },
        orderBy: { createdAt: 'desc' },
        take: 5,
      },
      profile: true,
    }
  })

// CREATE
  const newUser = await prisma.user.create({
    data: {
      name: 'Alice',
      email: 'alice@example.com',
      profile: {
        create: { bio: 'Software engineer' }  // nested create
      }
    }
  })

// UPDATE
  const updated = await prisma.user.update({
    where: { id: 1 },
    data: { name: 'Alicia' }
  })

// UPSERT (INSERT ... ON CONFLICT UPDATE)
  const upserted = await prisma.user.upsert({
    where: { email: 'alice@example.com' },
    create: { email: 'alice@example.com', name: 'Alice' },
    update: { name: 'Alice Updated' },
  })

// DELETE
  await prisma.user.delete({ where: { id: 1 } })
  await prisma.user.deleteMany({ where: { role: 'GUEST' } })

// AGGREGATES
  const count = await prisma.user.count({ where: { role: 'ADMIN' } })
  const stats = await prisma.post.aggregate({
    _count: true,
    _avg: { viewCount: true },
    _max: { createdAt: true },
  })

// GROUP BY
  const byRole = await prisma.user.groupBy({
    by: ['role'],
    _count: true,
  })
